        <?php $__currentLoopData = $calendarDays; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $day): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><div class="cal-cell <?php echo e(!$day['in_month']?'dim':''); ?> <?php echo e($day['date']->isToday()?'today':''); ?>"><span class="cal-cell-date"><?php echo e($day['date']->day); ?></span>
