            <?php $__currentLoopData = $timedDays; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $day): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><div class="cal-tg-daybody <?php echo e($day['date']->isToday()?'today':''); ?>" style="height:<?php echo e($gridHeight); ?>px">
