                <?php $__currentLoopData = $day['blocks']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $block): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><?php $event=$block['event']; $width=100/max(1,$day['columns']); ?>
