        <?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?>
    <?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><div class="cal-empty-state"><i class="fa-regular fa-calendar"></i><h2>No events found</h2><p>Create an event or adjust the selected filters.</p></div><?php endif; ?></section>
