        <?php $__currentLoopData = $lanes; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $lane): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><div class="cal-lane"><header class="cal-lane-head"><span class="tm-card-owner"><?php echo e(strtoupper(substr($lane['label'],0,1))); ?></span><span><b class="cal-lane-name"><?php echo e($lane['label']); ?></b><small class="cal-lane-sub"><?php echo e($lane['sub']); ?></small></span></header><div class="cal-lane-track"><?php for($offset=0;$offset<7;$offset++): ?><?php $laneDay=$periodStart->addDays($offset); ?><div class="cal-lane-cell <?php echo e($laneDay->isToday()?'today':''); ?>"><?php $__currentLoopData = $lane['events']->filter(fn($event)=>$event->starts_at?->setTimezone($calendarTimezone)->isSameDay($laneDay)); $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $event): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><?php $type=$eventTypeOf($event); ?><a x-show="!categoryHidden('<?php echo e($type); ?>')" class="cal-lane-pill" style="background:<?php echo e($eventColors[$type]??'#64748b'); ?>" href="<?php echo e(route('collaboration.calendar-events.index',$calendarQuery(['event_id'=>$event->id]))); ?>"><?php echo e($event->starts_at?->setTimezone($calendarTimezone)->format('g:i A')); ?> <?php echo e($event->title); ?></a><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></div><?php endfor; ?></div></div><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?>
